  -- item 10: Hitting mat (the one I already owned)
  SELECT id INTO v_section FROM bag_sections WHERE bag_id = v_bag AND name = $q$Mat$q$;
  SELECT id INTO v_item FROM bag_items WHERE bag_id = v_bag AND custom_name = $q$Hitting mat (the one I already owned)$q$;
  IF v_item IS NULL THEN
    INSERT INTO bag_items (bag_id, section_id, custom_name, brand, custom_description, why_chosen, notes, price_paid, purchase_date, item_type, specs, quantity, sort_index)
    VALUES (v_bag, v_section, $q$Hitting mat (the one I already owned)$q$, $q$Various$q$, $q$Owned before the build. Maker, size and price to be confirmed.$q$, $q$The mat I already had. I don't sell mats and I'm not going to. It's the one part of a garage sim that never folds, so it's the thing you still pick up before the car comes in.$q$, NULL, NULL, NULL, $q$physical_product$q$, $j${}$j$::jsonb, 1, 10)
    RETURNING id INTO v_item;
  ELSE
    UPDATE bag_items SET
      section_id = v_section,
      brand = $q$Various$q$,
      custom_description = $q$Owned before the build. Maker, size and price to be confirmed.$q$,
      why_chosen = $q$The mat I already had. I don't sell mats and I'm not going to. It's the one part of a garage sim that never folds, so it's the thing you still pick up before the car comes in.$q$,
      notes = NULL,
      price_paid = NULL,
      purchase_date = NULL,
      item_type = $q$physical_product$q$,
      specs = $j${}$j$::jsonb,
      quantity = 1,
      sort_index = 10
    WHERE id = v_item;
  END IF;
  IF v_first_item IS NULL THEN v_first_item := v_item; END IF;
  DELETE FROM links WHERE bag_item_id = v_item;

  -- Items in the bag that are not in this file are reported, never deleted.
  SELECT count(*) INTO v_stale FROM bag_items
  WHERE bag_id = v_bag AND custom_name NOT IN ($q$StowGolf fold-flat enclosure (factory sample)$q$, $q$Carl's Place Preferred impact screen$q$, $q$Ball bungees (about 90 per set)$q$, $q$Rapsodo MLM2PRO$q$, $q$Rapsodo Premium membership$q$, $q$BenQ TK710STi$q$, $q$Projector cart$q$, $q$Gaming laptop (existing)$q$, $q$GSPro$q$, $q$Hitting mat (the one I already owned)$q$);
  IF v_stale > 0 THEN
    RAISE NOTICE 'garage-sim: % item(s) in the bag are not in the file', v_stale;
  END IF;

  -- hero_item_id: the first item, only when the bag has none.
  IF v_first_item IS NOT NULL THEN
    UPDATE bags SET hero_item_id = v_first_item WHERE id = v_bag AND hero_item_id IS NULL;
  END IF;
  RAISE NOTICE 'garage-sim: bag %, 5 section(s), 10 item(s) upserted', v_bag;
END
$seed$;

-- 6. Summary: one row.
SELECT
  b.code,
  (SELECT count(*) FROM bag_sections s WHERE s.bag_id = b.id) AS sections,
  (SELECT count(*) FROM bag_items i WHERE i.bag_id = b.id) AS items,
  (SELECT count(*) FROM links l JOIN bag_items i ON i.id = l.bag_item_id WHERE i.bag_id = b.id) AS links
FROM bags b
WHERE b.owner_id = '2c3e503a-78ce-4a8d-ae37-60b4a16d916e'::uuid AND b.code = $q$garage-sim$q$;

COMMIT;
